(function(){'use strict';
var FONT_KEY='welog-font-lock-v2',STATE_KEY='welog-pair-sheet-v4';
var sheet=document.getElementById('sheet'),controls=document.getElementById('controls');if(!sheet)return;
function norm(v){v=v||'';if(/^KoPub Dotum/.test(v))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v))return'KoPub Batang Medium';if(v==='Noto Sans KR')return'Noto Sans KR';if(v==='__system__')return'__system__';return'Pretendard'}
function stack(v){v=norm(v);if(v==='KoPub Dotum Medium')return'WeLogExactDotum,sans-serif';if(v==='KoPub Batang Medium')return'WeLogExactBatang,serif';if(v==='Noto Sans KR')return'WeLogExactNoto,sans-serif';if(v==='__system__')return'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';return'WeLogExactPretendard,sans-serif'}
function stateFont(){try{return norm((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).font)}catch(e){return'Pretendard'}}
function locked(){return norm(localStorage.getItem(FONT_KEY)||stateFont())}
function applyFont(root){var f=stack(locked());document.documentElement.style.setProperty('--welog-locked-font',f);sheet.style.setProperty('font-family',f,'important');(root||sheet).querySelectorAll('*').forEach(function(n){if(!n.closest('.direct-sticker'))n.style.setProperty('font-family',f,'important')});var sel=controls&&controls.querySelector('select[data-path="font"]');if(sel)for(var i=0;i<sel.options.length;i++)if(norm(sel.options[i].value)===locked()){sel.selectedIndex=i;break}}
function lock(v){v=norm(v);localStorage.setItem(FONT_KEY,v);try{var s=JSON.parse(localStorage.getItem(STATE_KEY)||'{}');s.font=v;localStorage.setItem(STATE_KEY,JSON.stringify(s))}catch(e){}applyFont()}
if(controls){controls.addEventListener('change',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true);controls.addEventListener('input',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true)}
document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#tabs'))setTimeout(function(){applyFont()},30)},true);window.addEventListener('pageshow',function(){applyFont()});document.addEventListener('visibilitychange',function(){if(!document.hidden)applyFont()});applyFont();
function stripEditor(root){root.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.direct-crop-ui,.guide-line').forEach(function(n){n.remove()});root.querySelectorAll('.direct-sticker').forEach(function(n){n.style.outline='none'})}
function makeModal(){var m=document.querySelector('.welog-exact-shot');if(m)return m;m=document.createElement('div');m.className='welog-exact-shot';m.hidden=true;m.innerHTML='<section class="welog-exact-shot-dialog"><header class="welog-exact-shot-head"><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" aria-label="닫기">×</button></header><div class="welog-exact-shot-body"><div class="welog-preview-fit"></div></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('.welog-exact-shot-head button'))m.hidden=true});return m}
function preview(){applyFont();var m=makeModal(),fit=m.querySelector('.welog-preview-fit');fit.innerHTML='';var clone=sheet.cloneNode(true);clone.removeAttribute('id');clone.classList.add('welog-preview-live-clone');stripEditor(clone);applyFont(clone);clone.style.margin='0';clone.style.transform='none';clone.style.zoom='1';fit.appendChild(clone);m.hidden=false;requestAnimationFrame(function(){var body=m.querySelector('.welog-exact-shot-body'),bw=Math.max(1,body.clientWidth-32),bh=Math.max(1,body.clientHeight-32),w=Math.max(1,sheet.offsetWidth),h=Math.max(1,sheet.offsetHeight),scale=Math.min(1,bw/w,bh/h);fit.style.width=w+'px';fit.style.height=h+'px';fit.style.transform='scale('+scale+')';fit.style.transformOrigin='center center'})}
async function ready(){applyFont();if(document.fonts&&document.fonts.ready)await document.fonts.ready;var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
async function canvasPng(){await ready();if(!window.html2canvas)throw new Error('html2canvas unavailable');var w=Math.max(1,Math.round(sheet.offsetWidth)),h=Math.max(1,Math.round(sheet.offsetHeight));var canvas=await window.html2canvas(sheet,{scale:2,useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,width:w,height:h,windowWidth:Math.max(document.documentElement.clientWidth,w),windowHeight:Math.max(document.documentElement.clientHeight,h),scrollX:0,scrollY:0,onclone:function(doc){var s=doc.getElementById('sheet');if(!s)return;stripEditor(s);var f=stack(locked());s.style.setProperty('font-family',f,'important');s.querySelectorAll('*').forEach(function(n){if(!n.closest('.direct-sticker'))n.style.setProperty('font-family',f,'important')})}});return canvas}
async function save(){var btn=document.getElementById('printBtn');if(!btn)return;var old=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';try{var canvas=await canvasPng();var blob=await new Promise(function(resolve,reject){canvas.toBlob(function(b){b?resolve(b):reject(new Error('PNG blob failed'))},'image/png')});var url=URL.createObjectURL(blob),a=document.createElement('a'),name='WeLog';try{name=((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).pairName||name).trim()||name}catch(e){}a.href=url;a.download=name+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},3000)}catch(e){console.error('WeLog PNG failed',e);alert('PNG 저장에 실패했습니다.')}finally{btn.disabled=false;btn.textContent=old}}
function replace(id,fn){var old=document.getElementById(id);if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id=id;b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();fn()},true)}
replace('previewBtn',preview);replace('printBtn',save);
})();